#include <expected>
#include <iostream>
#include <string>

int main() {
    std::expected<int, std::string> result{42};
    std::cout << std::boolalpha << result.has_value() << "\n";
    std::cout << result.value() << "\n";
    std::expected<int, std::string> failed{
        std::unexpected(std::string{"Missing input"})};
    std::cout << failed.error() << "\n";
    std::cout << failed.value_or(0) << "\n";
}
